<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');$pid=(int)($_GET['petugas_id']??0);require_selected_petugas($pid);$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT ph.*,p.nama_petugas,p.kecamatan,k.nama_kegiatan,k.tujuan_akhir FROM progress_harian ph JOIN petugas p ON p.id_petugas=ph.id_petugas JOIN kegiatan k ON k.id_kegiatan=ph.id_kegiatan WHERE ph.id_progress=? AND ph.id_petugas=? AND p.id_user=?');$q->execute([$id,$pid,current_user()['id_user']]);$h=$q->fetch();if(!$h){http_response_code(403);exit('Akses progress ditolak.');}$s=$pdo->prepare('SELECT dp.* FROM detail_progress dp WHERE dp.id_progress=? ORDER BY dp.jam_mulai,dp.id_detail');$s->execute([$id]);$rows=$s->fetchAll();page_header('Detail Progress Harian');?><div class="card p-4 mb-3"><div class="d-flex justify-content-between"><div><h2 class="h5 fw-bold"><?=e($h['nama_petugas'])?></h2><div><?=e($h['nama_kegiatan'])?> · <?=e($h['kecamatan'])?> · <?=format_tanggal($h['tanggal'])?></div></div><a class="btn btn-light" href="<?=APP_BASE_URL?>/petugas/progress/index.php?id=<?=$pid?>">Kembali</a></div></div><?php foreach($rows as $i=>$d):?><div class="card p-4 mb-3"><h3 class="h6 fw-bold">Detail SLS #<?=$i+1?></h3><div class="row g-3"><div class="col-md-4"><strong>Desa/Kelurahan</strong><div><?=e($d['desa'])?></div></div><div class="col-md-4"><strong>SLS</strong><div><?=e($d['sls'])?></div></div><div class="col-md-4"><strong>Sub SLS</strong><div><?=e($d['sub_sls']??'-')?></div></div><div class="col-md-3"><strong>Waktu</strong><div><?=e(substr($d['jam_mulai'],0,5))?>–<?=e(substr($d['jam_selesai'],0,5))?></div></div><?php foreach(['uraian_kegiatan'=>'Uraian Kegiatan','permasalahan'=>'Permasalahan','pemecahan_masalah'=>'Pemecahan Masalah','output_tujuan'=>'Output/Tujuan'] as $key=>$label):if(trim((string)$d[$key])==='')continue;?><div class="col-md-6"><strong><?=e($label)?></strong><div><?=nl2br(e($d[$key]))?></div></div><?php endforeach;?></div><?php $f=$pdo->prepare('SELECT * FROM dokumentasi WHERE id_detail=?');$f->execute([$d['id_detail']]);$docs=$f->fetchAll();if($docs):?><div class="mt-3"><strong>Dokumentasi</strong><div class="d-flex flex-wrap gap-3 mt-2"><?php foreach($docs as $doc):?><a href="<?=APP_BASE_URL?>/petugas/dokumen/file.php?petugas_id=<?=$pid?>&id=<?=$doc['id_dokumentasi']?>" target="_blank"><?=e($doc['nama_file'])?></a><?php endforeach;?></div></div><?php endif;?></div><?php endforeach;?><?php page_footer();
